#include "ms_openfx.hpp"
namespace ms { class IdentityOfx final:public OpenFxPlugin{OfxPluginInfo info_{"org.motionstudio.Identity","Motion Studio Identity","Motion Studio","1.0","builtin"};public:const OfxPluginInfo&info()const override{return info_;}bool supports(const ImageBuffer&i)const override{return i.valid()&&i.format()==PixelFormat::RGBA8;}Error render(const ImageBuffer&i,ImageBuffer&o,const std::vector<OfxParam>&,double)override{if(!supports(i))return Error::make(ErrorCode::InvalidArgument,"OpenFX input unsupported");if(!o.copy_from(i))return Error::make(ErrorCode::OutOfMemory,"OpenFX output allocation failed");return Error::success();}}; Error OpenFxRegistry::register_plugin(std::shared_ptr<OpenFxPlugin>p){if(!p||p->info().identifier.empty())return Error::make(ErrorCode::InvalidArgument,"invalid OpenFX plugin");plugins_[p->info().identifier]=std::move(p);return Error::success();} bool OpenFxRegistry::remove(const std::string&i){return plugins_.erase(i)!=0;} std::shared_ptr<OpenFxPlugin>OpenFxRegistry::find(const std::string&i)const{auto x=plugins_.find(i);return x==plugins_.end()?nullptr:x->second;} std::vector<OfxPluginInfo>OpenFxRegistry::list()const{std::vector<OfxPluginInfo>o;for(auto&x:plugins_)o.push_back(x.second->info());return o;} Error OpenFxRegistry::apply(const std::string&i,const ImageBuffer&in,ImageBuffer&out,const std::vector<OfxParam>&p,double t)const{auto x=find(i);if(!x)return Error::make(ErrorCode::EffectNotFound,"OpenFX plugin not found",i);if(!x->supports(in))return Error::make(ErrorCode::EffectIncompatibleVersion,"OpenFX plugin does not support image format",i);return x->render(in,out,p,t);} std::shared_ptr<OpenFxPlugin>make_identity_ofx_plugin(){return std::make_shared<IdentityOfx>();} }
